package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() throws NumberFormatException {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X12345678") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
        assertTrue(NumberUtils.createNumber("#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X123456789") instanceof Long);
        // Very large hex
        assertTrue(NumberUtils.createNumber("0x12345678901234567890") instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_IntegerLongBigInt() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("2147483648") instanceof Long);
        assertTrue(NumberUtils.createNumber("9223372036854775808") instanceof BigInteger);
        assertTrue(NumberUtils.createNumber("-123") instanceof Integer);
    }

    @Test
    public void testCreateNumber_FloatDoubleBigDecimal() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123.45") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23E2") instanceof Double);
        // Fallback to BigDecimal for extreme precision
        assertTrue(NumberUtils.createNumber("1.12345678901234567890") instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_Suffixes() throws NumberFormatException {
        // Long suffix
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123L") instanceof Long);
        // BigInteger via Long suffix
        assertTrue(NumberUtils.createNumber("9223372036854775807L") instanceof Long);
        try {
            NumberUtils.createNumber("9223372036854775808L");
            // If it doesn't throw, it should be BigInteger
        } catch (NumberFormatException e) {
            // Expected if logic fails
        }

        // Float suffix
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);
        assertTrue(NumberUtils.createNumber("123.45f") instanceof Float);

        // Double suffix
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        NumberUtils.createNumber("123.45X");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExponentPosition() throws NumberFormatException {
        // This simulates the expPos < decPos check
        NumberUtils.createNumber("1e2.3"); 
    }

    @Test
    public void testCreateNumber_AllZerosPrecision() throws NumberFormatException {
        // Testing the allZeros logic to ensure it doesn't return a Float/Double if precision is lost
        // "0.000000000000000000000000000000000000001"
        Number n = NumberUtils.createNumber("0.000000000000000000000000000000000000001");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ZeroHandling() throws NumberFormatException {
        // Check allZeros logic for 0.0
        Number n = NumberUtils.createNumber("0.0");
        assertTrue(n instanceof Double || n instanceof Float);

        Number n2 = NumberUtils.createNumber("0.000");
        assertTrue(n2 instanceof Double || n2 instanceof Float);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_NonNumeric() throws NumberFormatException {
        NumberUtils.createNumber("abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_MalformedExponent() throws NumberFormatException {
        NumberUtils.createNumber("123e");
    }

    @Test
    public void testCreateNumber_NegativeHex() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
    }
}
